from django.contrib.auth.models import User
from rest_framework.decorators import api_view
from rest_framework.response import Response
from rest_framework import status
import re

@api_view(['POST'])
def signup(request):
    email = request.data.get('email', '').strip().lower()
    password = request.data.get('password', '')
    if not email or not password:
        return Response({'error': 'Email and password required'}, status=status.HTTP_400_BAD_REQUEST)
    if User.objects.filter(email__iexact=email).exists():
        return Response({'error': 'Email already registered'}, status=status.HTTP_400_BAD_REQUEST)
    if len(password) < 8 or not re.search(r'\d', password):
        return Response({'error': 'Password must be at least 8 characters and contain a digit'}, status=status.HTTP_400_BAD_REQUEST)
    user = User.objects.create_user(username=email, email=email, password=password)
    return Response({'message': 'User created'}, status=status.HTTP_201_CREATED)

from rest_framework import generics, permissions, serializers
from .models import Todo

class TodoSerializer(serializers.ModelSerializer):
    class Meta:
        model = Todo
        fields = ['id', 'title', 'completed']
        read_only_fields = ['id']

    def validate_title(self, value):
        if not value.strip():
            raise serializers.ValidationError('Title cannot be empty')
        if len(value) > 200:
            raise serializers.ValidationError('Title too long')
        return value

class TodoCreateView(generics.CreateAPIView):
    serializer_class = TodoSerializer
    permission_classes = [permissions.IsAuthenticated]

    def perform_create(self, serializer):
        serializer.save(user=self.request.user)

from rest_framework import generics, permissions
from rest_framework.pagination import PageNumberPagination
from .models import Todo
from .serializers import TodoSerializer

class TodoPagination(PageNumberPagination):
    page_size = 10

class TodoListView(generics.ListAPIView):
    serializer_class = TodoSerializer
    permission_classes = [permissions.IsAuthenticated]
    pagination_class = TodoPagination

    def get_queryset(self):
        return Todo.objects.filter(user=self.request.user).select_related('user').order_by('-id')
